    notifyInterestedUsers(seller, productSize, bidPrice);

    // 8. SaleBid 반환
    return saleBid;
}

private void notifyInterestedUsers(User seller, ProductSize productSize, int bidPrice) {
    ProductColor productColor = productSize.getProductColor();
    String message = String.format("%s %s 사이즈에 새 판매 입찰이 등록되었습니다. 판매 희망가 %,d원",
            productColor.getProduct().getName(), productSize.getSize(), bidPrice);

    List<Interest> interests = interestRepository.findAllByProductColor(productColor);
    for (Interest interest : interests) {
        User user = interest.getUser();
        if (user.getId().equals(seller.getId()) || !user.isActive()) {
            continue;
        }
        notificationCommandService.createNotification(
                user.getId(), NotificationCategory.SHOPPING, NotificationType.FAVORITE, message);
    }
}

